example.code:
.layout {
  display: grid;
  grid-template-columns: 16rem 1fr;
  gap: 2rem;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

@layer reset, components, utilities;

@layer components {
  .card p { color: var(--ink-2); }
}

@layer utilities {
  .text-accent { color: var(--accent); }
}

*, *::before, *::after {
  box-sizing: border-box;
}

.card {
  width: 20rem;
  padding: 1rem;
  border: 1px solid #ddd;
}

.card {
  position: relative;
}

.badge {
  position: absolute;
  top: -0.5rem;
  right: -0.5rem;
}

code.code:
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1.5rem;
}
